mapper.select:


     and ow.user_id = #{userId}
     and ou.phone_number = #{phoneNumber}
     and ou.username = #{username}
     and pu.username = #{parentUsername}

        and (
            gwa.wallet_address like concat('%', #{accountAddress}, '%')
            or gwa.wallet_address_mask like concat('%', #{accountAddress}, '%')
        )

     and gwa.type = #{withdrawalType}
     and ow.status = #{status}
     and ou.is_fake = #{isFake}
     and ow.transaction_type = #{transactionType}
     and ow.is_hidden = #{isHidden}

        and ow.amount >= #{params.amountMin}


        and ow.amount <= #{params.amountMax}


        and ow.create_time >= #{params.beginTime}


        and ow.create_time <= #{params.endTime}


order by ow.create_time desc

