update order_withdrawal
user_id = #{userId}, amount = #{amount}, withdrawal_type = #{withdrawalType}, status = #{status}, create_time = #{createTime}, remarks = #{remarks}, transaction_type = #{transactionType}, order_number = #{orderNumber}, is_hidden = #{isHidden}, fee = #{fee}, withdrawal_account_id = #{withdrawalAccountId}, update_by = #{updateBy}, update_time = now(3),
where id = #{id}

update withdrawal_daily_quota
set reserved_amount = GREATEST(0, reserved_amount - #{amount}), update_time = NOW(3)
where business_date = #{businessDate}
